insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('1ebb100b-035e-467e-af1a-cd7f3b5b58d4', 'af13c9a6-3073-4e40-8a59-424a699b978b', null, 'topic'::public.curated_course_node_type, 'Vectors, Matrices, and Geometry in Space', 'Multivariable calculus begins with a language for position, direction, geometry, and linear change. Vectors describe quantities with magnitude and direction, while elementary matrix notation prepares students to express systems, transformations, and derivatives compactly.', 0),
  ('b382cd6a-4ff0-45c0-9d6c-0422ae4d795f', 'af13c9a6-3073-4e40-8a59-424a699b978b', '1ebb100b-035e-467e-af1a-cd7f3b5b58d4', 'subtopic'::public.curated_course_node_type, 'Coordinate systems and geometry in two and three dimensions', 'A reliable spatial picture is essential for setting domains, interpreting level sets, and choosing coordinates that fit a problem''s symmetry.', 0),
  ('b64f1d4d-b933-4a41-95e8-69406b7211bf', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'b382cd6a-4ff0-45c0-9d6c-0422ae4d795f', 'concept'::public.curated_course_node_type, 'Cartesian coordinates, distance, midpoint, spheres, cylinders, and traces', null, 0),
  ('8a5b8c16-e00d-4078-af36-2d71388b6e5d', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'b382cd6a-4ff0-45c0-9d6c-0422ae4d795f', 'concept'::public.curated_course_node_type, 'Cylindrical and spherical coordinates as geometric descriptions', null, 1),
  ('ca2a50bd-b590-4bfb-8e6d-8c0986b2d033', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'b382cd6a-4ff0-45c0-9d6c-0422ae4d795f', 'concept'::public.curated_course_node_type, 'Quadratic surfaces: ellipsoids, paraboloids, hyperboloids, and cones', null, 2),
  ('8051c216-7577-46a3-bde1-f4f1238e70e9', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'b382cd6a-4ff0-45c0-9d6c-0422ae4d795f', 'concept'::public.curated_course_node_type, 'Sketching surfaces from equations, cross-sections, symmetry, and intercepts', null, 3),
  ('2b5d7121-f886-4dbf-aa9e-5b9b1389f2ad', 'af13c9a6-3073-4e40-8a59-424a699b978b', '1ebb100b-035e-467e-af1a-cd7f3b5b58d4', 'subtopic'::public.curated_course_node_type, 'Vector algebra and geometric products', 'Vector operations convert geometric questions about angles, projections, areas, orientation, force, and torque into calculations.', 1),
  ('937f7130-f9da-4e06-b227-80b7e50fb968', 'af13c9a6-3073-4e40-8a59-424a699b978b', '2b5d7121-f886-4dbf-aa9e-5b9b1389f2ad', 'concept'::public.curated_course_node_type, 'Components, magnitude, unit vectors, addition, and scalar multiplication', null, 0),
  ('ba8d95ce-29ca-466f-87fe-d18cbe7ba377', 'af13c9a6-3073-4e40-8a59-424a699b978b', '2b5d7121-f886-4dbf-aa9e-5b9b1389f2ad', 'concept'::public.curated_course_node_type, 'Dot product, angles, orthogonality, projection, and work', null, 1),
  ('8221c90e-9634-4a68-a058-ccabe65d9d54', 'af13c9a6-3073-4e40-8a59-424a699b978b', '2b5d7121-f886-4dbf-aa9e-5b9b1389f2ad', 'concept'::public.curated_course_node_type, 'Cross product, orientation, area, torque, and the scalar triple product', null, 2),
  ('3bdfa535-3fe0-457a-934b-e6fbd6ab976b', 'af13c9a6-3073-4e40-8a59-424a699b978b', '2b5d7121-f886-4dbf-aa9e-5b9b1389f2ad', 'concept'::public.curated_course_node_type, 'Vector identities and proof-aware geometric reasoning', null, 3),
  ('ce0883e5-aa3a-4380-97fa-2f0c7691670e', 'af13c9a6-3073-4e40-8a59-424a699b978b', '1ebb100b-035e-467e-af1a-cd7f3b5b58d4', 'subtopic'::public.curated_course_node_type, 'Lines, planes, matrices, and linear systems', 'Parametric descriptions and small matrix systems connect spatial geometry to the derivative-matrix viewpoint used later in the course.', 2),
  ('c1f34c46-f16a-4ffc-a7e5-5b2c05fd6234', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'ce0883e5-aa3a-4380-97fa-2f0c7691670e', 'concept'::public.curated_course_node_type, 'Vector and parametric equations of lines', null, 0),
  ('9a7d9ac6-722d-499c-9d0b-e60374b18431', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'ce0883e5-aa3a-4380-97fa-2f0c7691670e', 'concept'::public.curated_course_node_type, 'Normal-vector equations of planes and distances to planes', null, 1),
  ('325392b3-f1ba-47e6-97b0-3274c9e14eec', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'ce0883e5-aa3a-4380-97fa-2f0c7691670e', 'concept'::public.curated_course_node_type, 'Intersections, parallelism, skew lines, and geometric constraints', null, 2),
  ('9f825657-d7ef-4a58-bdea-d84d94e74579', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'ce0883e5-aa3a-4380-97fa-2f0c7691670e', 'concept'::public.curated_course_node_type, 'Matrix notation, linear maps, determinants, and solving small systems', null, 3),
  ('9ad09a21-e8b7-48ac-a487-7e85e428cd74', 'af13c9a6-3073-4e40-8a59-424a699b978b', null, 'topic'::public.curated_course_node_type, 'Vector-Valued Functions and Motion', 'Vector-valued functions describe curves and trajectories in space. Their derivatives separate motion into velocity, acceleration, speed, direction, and curvature, creating a bridge from single-variable calculus to mechanics and field-based models.', 1),
  ('a396984f-243b-4ce7-86c4-74efc49eb410', 'af13c9a6-3073-4e40-8a59-424a699b978b', '9ad09a21-e8b7-48ac-a487-7e85e428cd74', 'subtopic'::public.curated_course_node_type, 'Curves and vector-valued functions', 'A parameter lets all coordinates vary together, representing paths that may loop, intersect, or move through three dimensions.', 0),
  ('50748532-9182-401d-936c-2b8a05ed8ebb', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'a396984f-243b-4ce7-86c4-74efc49eb410', 'concept'::public.curated_course_node_type, 'Parametric curves, orientation, domains, and traces', null, 0),
  ('759d9103-80e1-43e0-8ec0-8a8102d28810', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'a396984f-243b-4ce7-86c4-74efc49eb410', 'concept'::public.curated_course_node_type, 'Limits, continuity, derivatives, and integrals component by component', null, 1),
  ('294a8031-43ee-4786-833b-1f4782d6245b', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'a396984f-243b-4ce7-86c4-74efc49eb410', 'concept'::public.curated_course_node_type, 'Tangent lines and smoothness of a parametrized curve', null, 2),
  ('a974acec-5c09-47cc-a043-c6918b4b937c', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'a396984f-243b-4ce7-86c4-74efc49eb410', 'concept'::public.curated_course_node_type, 'Reparameterization and the role of the parameter', null, 3),
  ('8061558c-15f3-48d8-98ee-d6e06e34f631', 'af13c9a6-3073-4e40-8a59-424a699b978b', '9ad09a21-e8b7-48ac-a487-7e85e428cd74', 'subtopic'::public.curated_course_node_type, 'Position, velocity, acceleration, and speed', 'Derivatives of a position vector give a complete kinematic description and make units and reference frames explicit.', 1),
  ('5fde768c-5934-4768-8f0e-f893784b0cea', 'af13c9a6-3073-4e40-8a59-424a699b978b', '8061558c-15f3-48d8-98ee-d6e06e34f631', 'concept'::public.curated_course_node_type, 'Position, displacement, velocity, speed, and acceleration', null, 0),
  ('a8afaf06-efdc-4407-8a22-3357e59f9e39', 'af13c9a6-3073-4e40-8a59-424a699b978b', '8061558c-15f3-48d8-98ee-d6e06e34f631', 'concept'::public.curated_course_node_type, 'Projectile and orbital-style motion under simplified force laws', null, 1),
  ('d0e2724f-8114-4706-9649-42b6b8a3a795', 'af13c9a6-3073-4e40-8a59-424a699b978b', '8061558c-15f3-48d8-98ee-d6e06e34f631', 'concept'::public.curated_course_node_type, 'Recovering position from velocity or acceleration and initial data', null, 2),
  ('64c116eb-333a-452c-b25e-2c965b75d6a1', 'af13c9a6-3073-4e40-8a59-424a699b978b', '8061558c-15f3-48d8-98ee-d6e06e34f631', 'concept'::public.curated_course_node_type, 'Interpreting vector components, signs, and units', null, 3),
  ('9de748db-808b-488c-b88e-74a1507f01ac', 'af13c9a6-3073-4e40-8a59-424a699b978b', '9ad09a21-e8b7-48ac-a487-7e85e428cd74', 'subtopic'::public.curated_course_node_type, 'Arc length, curvature, and moving frames', 'Arc length measures distance along a curve, while curvature and moving unit vectors describe how sharply and in what direction a trajectory turns.', 2),
  ('eb038e9a-c062-4909-9bb9-d21b24879516', 'af13c9a6-3073-4e40-8a59-424a699b978b', '9de748db-808b-488c-b88e-74a1507f01ac', 'concept'::public.curated_course_node_type, 'Arc length and the arc-length parameter', null, 0),
  ('76e88340-d1ac-4399-8752-939fca10e772', 'af13c9a6-3073-4e40-8a59-424a699b978b', '9de748db-808b-488c-b88e-74a1507f01ac', 'concept'::public.curated_course_node_type, 'Unit tangent vector and curvature', null, 1),
  ('36666d6d-8b1f-4dd2-b623-82a78a05b7b0', 'af13c9a6-3073-4e40-8a59-424a699b978b', '9de748db-808b-488c-b88e-74a1507f01ac', 'concept'::public.curated_course_node_type, 'Principal normal and tangential-normal acceleration components', null, 2),
  ('5c7d4cf3-998a-4baf-b39b-059a60b57e22', 'af13c9a6-3073-4e40-8a59-424a699b978b', '9de748db-808b-488c-b88e-74a1507f01ac', 'concept'::public.curated_course_node_type, 'Optional enrichment: binormal vector, torsion, and Frenet frame', null, 3),
  ('59efbe89-f897-49e2-bc17-868a1b4bf196', 'af13c9a6-3073-4e40-8a59-424a699b978b', null, 'topic'::public.curated_course_node_type, 'Functions of Several Variables, Limits, and Continuity', 'Functions of several variables model quantities influenced by multiple inputs. This unit develops their geometry and the path-independent limiting behavior required before derivatives and approximations can be trusted.', 2),
  ('755951ea-6978-4160-a537-3134fda83d41', 'af13c9a6-3073-4e40-8a59-424a699b978b', '59efbe89-f897-49e2-bc17-868a1b4bf196', 'subtopic'::public.curated_course_node_type, 'Domains, graphs, and level sets', 'Different representations reveal different features: a graph shows height, a level set shows where output is constant, and a domain records which inputs are meaningful.', 0),
  ('c6baf708-a6e8-4ff2-8a69-5f73346593a0', 'af13c9a6-3073-4e40-8a59-424a699b978b', '755951ea-6978-4160-a537-3134fda83d41', 'concept'::public.curated_course_node_type, 'Functions from R^n to R and from R^n to R^m', null, 0),
  ('b88e2e44-3967-43f6-b198-400105c5b7d4', 'af13c9a6-3073-4e40-8a59-424a699b978b', '755951ea-6978-4160-a537-3134fda83d41', 'concept'::public.curated_course_node_type, 'Domains, ranges, graphs, level curves, level surfaces, and contour maps', null, 1),
  ('711ccfb3-853d-4382-8f1c-05da67f49efc', 'af13c9a6-3073-4e40-8a59-424a699b978b', '755951ea-6978-4160-a537-3134fda83d41', 'concept'::public.curated_course_node_type, 'Sections, traces, and data-based visualizations', null, 2),
  ('b82e52ab-2b00-437b-a920-7d3729121430', 'af13c9a6-3073-4e40-8a59-424a699b978b', '755951ea-6978-4160-a537-3134fda83d41', 'concept'::public.curated_course_node_type, 'Applications to temperature, concentration, cost, utility, and energy landscapes', null, 3),
  ('92121401-684f-4ac9-a87d-8a21c5554a6d', 'af13c9a6-3073-4e40-8a59-424a699b978b', '59efbe89-f897-49e2-bc17-868a1b4bf196', 'subtopic'::public.curated_course_node_type, 'Multivariable limits', 'A multivariable limit must be the same along every possible approach, so checking a few paths can disprove a limit but usually cannot prove one.', 1),
  ('bdea3218-2b59-4b39-9b06-6baf7636136a', 'af13c9a6-3073-4e40-8a59-424a699b978b', '92121401-684f-4ac9-a87d-8a21c5554a6d', 'concept'::public.curated_course_node_type, 'Neighborhoods, distance, and approaching a point in multiple dimensions', null, 0),
  ('6db849cb-02dc-4787-b9ea-08da78b98e80', 'af13c9a6-3073-4e40-8a59-424a699b978b', '92121401-684f-4ac9-a87d-8a21c5554a6d', 'concept'::public.curated_course_node_type, 'Limits by substitution and algebraic simplification', null, 1),
  ('69d9c161-7d05-4a9b-9563-989a147d9ea2', 'af13c9a6-3073-4e40-8a59-424a699b978b', '92121401-684f-4ac9-a87d-8a21c5554a6d', 'concept'::public.curated_course_node_type, 'Path tests for nonexistence', null, 2),
  ('ae725368-e03f-44b8-bd2b-0f6e0ff8bb25', 'af13c9a6-3073-4e40-8a59-424a699b978b', '92121401-684f-4ac9-a87d-8a21c5554a6d', 'concept'::public.curated_course_node_type, 'Bounding, squeeze arguments, and polar-coordinate estimates for existence', null, 3),
  ('6e336251-8b5c-46f4-9cde-bd37787c47f7', 'af13c9a6-3073-4e40-8a59-424a699b978b', '59efbe89-f897-49e2-bc17-868a1b4bf196', 'subtopic'::public.curated_course_node_type, 'Continuity and local behavior', 'Continuity ensures that nearby inputs produce nearby outputs and supports composition, extreme-value arguments, integration, and numerical modeling.', 2),
  ('5f6389e1-cfe4-4bd1-9290-a9054f5408ed', 'af13c9a6-3073-4e40-8a59-424a699b978b', '6e336251-8b5c-46f4-9cde-bd37787c47f7', 'concept'::public.curated_course_node_type, 'Continuity at a point and on a region', null, 0),
  ('4ae99488-db01-43d3-9097-06f934edce24', 'af13c9a6-3073-4e40-8a59-424a699b978b', '6e336251-8b5c-46f4-9cde-bd37787c47f7', 'concept'::public.curated_course_node_type, 'Continuity of sums, products, quotients, and compositions', null, 1),
  ('d0c58ccf-9533-486f-b972-e4d5b5232ebc', 'af13c9a6-3073-4e40-8a59-424a699b978b', '6e336251-8b5c-46f4-9cde-bd37787c47f7', 'concept'::public.curated_course_node_type, 'Boundary behavior and discontinuity classification', null, 2),
  ('8ee2fb5c-a6f9-487e-bbf8-7ad42a7d24d0', 'af13c9a6-3073-4e40-8a59-424a699b978b', '6e336251-8b5c-46f4-9cde-bd37787c47f7', 'concept'::public.curated_course_node_type, 'Closed and bounded regions, intuitive compactness and existence of extrema', null, 3),
  ('e862999e-9780-4c54-8a35-4c735b7b49ed', 'af13c9a6-3073-4e40-8a59-424a699b978b', null, 'topic'::public.curated_course_node_type, 'Partial Derivatives, Differentiability, and the Chain Rule', 'Partial derivatives measure one-input-at-a-time change, but differentiability is the stronger claim that one linear map approximates all small changes at once. This distinction is central to reliable modeling, optimization, and computation.', 3),
  ('8f4ef7f8-b533-40f6-8c39-66dc9adec01c', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'e862999e-9780-4c54-8a35-4c735b7b49ed', 'subtopic'::public.curated_course_node_type, 'Partial and higher-order derivatives', 'Holding other inputs fixed isolates sensitivity to one variable and produces the building blocks for gradients, Hessians, and differential equations.', 0),
  ('86a4f8a5-e727-4962-a22e-65e03d59d0d5', 'af13c9a6-3073-4e40-8a59-424a699b978b', '8f4ef7f8-b533-40f6-8c39-66dc9adec01c', 'concept'::public.curated_course_node_type, 'First partial derivatives from formulas, tables, and limits', null, 0),
  ('05165f03-c165-4308-92c8-3653667884ba', 'af13c9a6-3073-4e40-8a59-424a699b978b', '8f4ef7f8-b533-40f6-8c39-66dc9adec01c', 'concept'::public.curated_course_node_type, 'Units and ceteris-paribus interpretation', null, 1),
  ('36738dd2-cf44-4ccb-968c-b130ee935f67', 'af13c9a6-3073-4e40-8a59-424a699b978b', '8f4ef7f8-b533-40f6-8c39-66dc9adec01c', 'concept'::public.curated_course_node_type, 'Second and mixed partial derivatives', null, 2),
  ('c4952753-9a25-48ee-a406-7dc9e8589936', 'af13c9a6-3073-4e40-8a59-424a699b978b', '8f4ef7f8-b533-40f6-8c39-66dc9adec01c', 'concept'::public.curated_course_node_type, 'Clairaut''s theorem and the conditions for equality of mixed partials', null, 3),
  ('a5e56199-b447-4704-996f-16c151e54960', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'e862999e-9780-4c54-8a35-4c735b7b49ed', 'subtopic'::public.curated_course_node_type, 'Differentiability, tangent planes, and total differentials', 'Differentiability means the function has a best local linear approximation, not merely that its partial derivatives exist.', 1),
  ('a8426d31-b0b7-4e7f-840f-1b76c4ebb92c', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'a5e56199-b447-4704-996f-16c151e54960', 'concept'::public.curated_course_node_type, 'Tangent planes and linearization', null, 0),
  ('650e5097-2f63-4723-bf4e-dcd9a656abeb', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'a5e56199-b447-4704-996f-16c151e54960', 'concept'::public.curated_course_node_type, 'Total differentials and propagated measurement error', null, 1),
  ('7178829f-50ef-4d90-9c4a-131cb8e6923f', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'a5e56199-b447-4704-996f-16c151e54960', 'concept'::public.curated_course_node_type, 'Sufficient conditions for differentiability and counterexamples', null, 2),
  ('238ca7e6-e612-46d8-bae5-dcf78fb2ea97', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'a5e56199-b447-4704-996f-16c151e54960', 'concept'::public.curated_course_node_type, 'Derivative matrices and the Jacobian as a linear map', null, 3),
  ('67960bb7-d78b-4f25-b7d3-5e57d2027767', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'e862999e-9780-4c54-8a35-4c735b7b49ed', 'subtopic'::public.curated_course_node_type, 'Multivariable chain rules and implicit differentiation', 'The chain rule tracks how change propagates through a dependency network and provides the derivative of a composition of multivariable maps.', 2),
  ('a6b87700-17b8-4de9-a052-b32a738bb219', 'af13c9a6-3073-4e40-8a59-424a699b978b', '67960bb7-d78b-4f25-b7d3-5e57d2027767', 'concept'::public.curated_course_node_type, 'Chain rule along a parametrized path', null, 0),
  ('fa7fbf82-a7be-4296-9777-80aaade2cf33', 'af13c9a6-3073-4e40-8a59-424a699b978b', '67960bb7-d78b-4f25-b7d3-5e57d2027767', 'concept'::public.curated_course_node_type, 'Tree diagrams and dependency graphs', null, 1),
  ('542ddb06-5411-4126-b91f-ae6cc1dd66cd', 'af13c9a6-3073-4e40-8a59-424a699b978b', '67960bb7-d78b-4f25-b7d3-5e57d2027767', 'concept'::public.curated_course_node_type, 'Matrix form of the chain rule for R^n to R^m maps', null, 2),
  ('4537bf09-e5d5-4fb3-9f32-f4f1b1d92fde', 'af13c9a6-3073-4e40-8a59-424a699b978b', '67960bb7-d78b-4f25-b7d3-5e57d2027767', 'concept'::public.curated_course_node_type, 'Implicit differentiation and sensitivity in constrained relationships', null, 3),
  ('f877c685-8da7-46a1-bec7-5b6718b185d3', 'af13c9a6-3073-4e40-8a59-424a699b978b', null, 'topic'::public.curated_course_node_type, 'Gradient, Directional Derivatives, and Local Approximation', 'The gradient packages all first-order information for a scalar field. It points in the direction of steepest increase, stands perpendicular to level sets, and drives approximation, optimization, flux, and field models.', 4),
  ('c7b7e9ab-84dc-473a-86f0-1bb5426a9746', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'f877c685-8da7-46a1-bec7-5b6718b185d3', 'subtopic'::public.curated_course_node_type, 'Directional derivatives and the gradient', 'A directional derivative asks how a scalar field changes along a chosen unit direction. The gradient answers all such questions through one dot product.', 0),
  ('85dc6b70-b6a2-42cb-8d92-919969373309', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'c7b7e9ab-84dc-473a-86f0-1bb5426a9746', 'concept'::public.curated_course_node_type, 'Directional derivative from a path and from the gradient formula', null, 0),
  ('7326ed1e-fbed-48f8-8988-e2bfc4add043', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'c7b7e9ab-84dc-473a-86f0-1bb5426a9746', 'concept'::public.curated_course_node_type, 'Unit-direction requirement and normalization', null, 1),
  ('15c27e90-b8f0-4530-a8a2-c5068585d3d5', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'c7b7e9ab-84dc-473a-86f0-1bb5426a9746', 'concept'::public.curated_course_node_type, 'Maximum rate of change and steepest ascent or descent', null, 2),
  ('340817b4-12e5-417f-8d11-8973c3f6c268', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'c7b7e9ab-84dc-473a-86f0-1bb5426a9746', 'concept'::public.curated_course_node_type, 'Gradient orthogonality to level curves and level surfaces', null, 3),
  ('55ce51dd-d601-4f79-956e-56e6ae7f1392', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'f877c685-8da7-46a1-bec7-5b6718b185d3', 'subtopic'::public.curated_course_node_type, 'Tangent objects and normal vectors', 'Gradients supply normal vectors to implicit curves and surfaces, making tangent lines and tangent planes systematic.', 1),
  ('06a702a9-8bc6-4799-8556-27611d9df2c7', 'af13c9a6-3073-4e40-8a59-424a699b978b', '55ce51dd-d601-4f79-956e-56e6ae7f1392', 'concept'::public.curated_course_node_type, 'Tangent lines to level curves', null, 0),
  ('e06aca58-41c3-4652-b955-bbcc9efdc6fa', 'af13c9a6-3073-4e40-8a59-424a699b978b', '55ce51dd-d601-4f79-956e-56e6ae7f1392', 'concept'::public.curated_course_node_type, 'Tangent planes and normal lines to level surfaces', null, 1),
  ('4babd5c1-2257-4290-a81a-0fd7e12d4b6e', 'af13c9a6-3073-4e40-8a59-424a699b978b', '55ce51dd-d601-4f79-956e-56e6ae7f1392', 'concept'::public.curated_course_node_type, 'Angle of intersection and orthogonality', null, 2),
  ('21697e6a-56b2-4a54-9e1b-b0d4cbb46364', 'af13c9a6-3073-4e40-8a59-424a699b978b', '55ce51dd-d601-4f79-956e-56e6ae7f1392', 'concept'::public.curated_course_node_type, 'Applications to terrain, thermodynamics, fields, and implicit geometry', null, 3),
  ('e8eda4df-469b-42df-9301-19e332045210', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'f877c685-8da7-46a1-bec7-5b6718b185d3', 'subtopic'::public.curated_course_node_type, 'First- and second-order Taylor approximation', 'Taylor approximation extends tangent-plane reasoning by using gradient and curvature information to predict nearby values and assess local error.', 2),
  ('87ac5e5b-343b-4272-a3e0-cbcee1359d85', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'e8eda4df-469b-42df-9301-19e332045210', 'concept'::public.curated_course_node_type, 'First-order approximation and differentials', null, 0),
  ('d75e48f6-cc5e-4c6e-b0d4-df368ad0ae6f', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'e8eda4df-469b-42df-9301-19e332045210', 'concept'::public.curated_course_node_type, 'Jacobian-based approximation for vector-valued maps', null, 1),
  ('0601adda-21d2-41d5-a5fb-46b8495fae50', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'e8eda4df-469b-42df-9301-19e332045210', 'concept'::public.curated_course_node_type, 'Hessian matrix and quadratic terms', null, 2),
  ('ab328860-e971-4d9b-afb2-9d95c5d875a1', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'e8eda4df-469b-42df-9301-19e332045210', 'concept'::public.curated_course_node_type, 'Error, scaling, sensitivity, and the limits of local models', null, 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('f8d6c9c5-4175-4806-9753-56e763a25dbf', 'af13c9a6-3073-4e40-8a59-424a699b978b', null, 'topic'::public.curated_course_node_type, 'Unconstrained and Constrained Optimization', 'Optimization identifies best feasible choices in design, economics, science, and operations. A world-class treatment combines geometric intuition, derivative tests, boundary analysis, and careful interpretation rather than relying on formulas alone.', 5),
  ('f4a3c6ea-78fa-4935-a7ba-a0ad109b12be', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'f8d6c9c5-4175-4806-9753-56e763a25dbf', 'subtopic'::public.curated_course_node_type, 'Critical points and local classification', 'At an interior differentiable optimum the gradient vanishes, but a critical point may be a maximum, minimum, saddle, or inconclusive case.', 0),
  ('7d0b4b22-2ae6-4b1b-9dd7-3de16335a8d5', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'f4a3c6ea-78fa-4935-a7ba-a0ad109b12be', 'concept'::public.curated_course_node_type, 'Critical points and stationary conditions', null, 0),
  ('adc0cbea-306f-4a31-a9b3-1b026be917af', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'f4a3c6ea-78fa-4935-a7ba-a0ad109b12be', 'concept'::public.curated_course_node_type, 'Hessian matrix and the two-variable second-derivative test', null, 1),
  ('e0a5caf6-95ed-427e-8948-e14ddc2d7302', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'f4a3c6ea-78fa-4935-a7ba-a0ad109b12be', 'concept'::public.curated_course_node_type, 'Positive and negative definiteness as enrichment', null, 2),
  ('f012e720-544c-4db7-b99c-9b79706f6bc6', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'f4a3c6ea-78fa-4935-a7ba-a0ad109b12be', 'concept'::public.curated_course_node_type, 'Saddle points, degeneracy, and inconclusive tests', null, 3),
  ('4ec91156-d59e-4b7a-8a8e-47381686b419', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'f8d6c9c5-4175-4806-9753-56e763a25dbf', 'subtopic'::public.curated_course_node_type, 'Global extrema and boundary analysis', 'Global optimization requires a complete search over the interior and boundary of the feasible region, supported by an existence theorem when appropriate.', 1),
  ('99c4b582-d718-40d2-9ed4-bd4ac79cf145', 'af13c9a6-3073-4e40-8a59-424a699b978b', '4ec91156-d59e-4b7a-8a8e-47381686b419', 'concept'::public.curated_course_node_type, 'Extreme Value Theorem on closed, bounded regions', null, 0),
  ('29bc2097-bbbf-4003-a23b-26d712e9bbb4', 'af13c9a6-3073-4e40-8a59-424a699b978b', '4ec91156-d59e-4b7a-8a8e-47381686b419', 'concept'::public.curated_course_node_type, 'Boundary parameterization and endpoint checks', null, 1),
  ('e0a8c304-6045-420a-97a6-127ca58d8a8a', 'af13c9a6-3073-4e40-8a59-424a699b978b', '4ec91156-d59e-4b7a-8a8e-47381686b419', 'concept'::public.curated_course_node_type, 'Piecewise or non-smooth feasible boundaries', null, 2),
  ('9378c64c-9eb2-40d5-a103-3046cd9d17ef', 'af13c9a6-3073-4e40-8a59-424a699b978b', '4ec91156-d59e-4b7a-8a8e-47381686b419', 'concept'::public.curated_course_node_type, 'Comparing all candidates and interpreting feasibility', null, 3),
  ('888a73ae-5f7c-469a-8376-26285a71354d', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'f8d6c9c5-4175-4806-9753-56e763a25dbf', 'subtopic'::public.curated_course_node_type, 'Lagrange multipliers and applications', 'At a smooth constrained optimum, objective and constraint gradients align. The multiplier can also carry a useful marginal or sensitivity meaning.', 2),
  ('a0e2521a-315b-4e1b-a0d5-e798c7c6fcab', 'af13c9a6-3073-4e40-8a59-424a699b978b', '888a73ae-5f7c-469a-8376-26285a71354d', 'concept'::public.curated_course_node_type, 'One equality constraint and the gradient-parallel condition', null, 0),
  ('ff801774-cfa4-4cce-88e8-c099b9fe98fc', 'af13c9a6-3073-4e40-8a59-424a699b978b', '888a73ae-5f7c-469a-8376-26285a71354d', 'concept'::public.curated_course_node_type, 'Solving the multiplier system and checking candidates', null, 1),
  ('f107737b-0509-46f7-99d7-cec0f88f7be4', 'af13c9a6-3073-4e40-8a59-424a699b978b', '888a73ae-5f7c-469a-8376-26285a71354d', 'concept'::public.curated_course_node_type, 'Multiple constraints and constraint qualification as enrichment', null, 2),
  ('0d5b8307-857e-46fe-b87c-e4bdd1653914', 'af13c9a6-3073-4e40-8a59-424a699b978b', '888a73ae-5f7c-469a-8376-26285a71354d', 'concept'::public.curated_course_node_type, 'Engineering design, economic allocation, chemistry, and least-squares examples', null, 3),
  ('c86c562e-5d48-4b58-8ada-4d7c90d6a024', 'af13c9a6-3073-4e40-8a59-424a699b978b', null, 'topic'::public.curated_course_node_type, 'Double Integrals and Integration over Planar Regions', 'Double integrals accumulate density, probability, cost, mass, or another local quantity across a two-dimensional region. The main intellectual work is describing the region and choosing an efficient order or coordinate system.', 6),
  ('d788b710-9f37-4391-adb3-70a99c21f502', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'c86c562e-5d48-4b58-8ada-4d7c90d6a024', 'subtopic'::public.curated_course_node_type, 'Riemann sums and iterated integrals', 'A double integral is the limit of weighted sums over small area elements. Fubini''s theorem converts many such limits into repeated one-variable integrals.', 0),
  ('3c43f3fe-6d95-4f38-bf76-c3b35ec4ebc2', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'd788b710-9f37-4391-adb3-70a99c21f502', 'concept'::public.curated_course_node_type, 'Double Riemann sums and signed volume', null, 0),
  ('7ead18bc-5e45-48ef-95d3-955157c012d1', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'd788b710-9f37-4391-adb3-70a99c21f502', 'concept'::public.curated_course_node_type, 'Fubini''s theorem and iterated integrals on rectangles', null, 1),
  ('1a2579c7-d62c-45f4-bd21-8e4f8df1037f', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'd788b710-9f37-4391-adb3-70a99c21f502', 'concept'::public.curated_course_node_type, 'Average value over a region', null, 2),
  ('24cd1808-cbf3-45dd-85ea-feed018bc756', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'd788b710-9f37-4391-adb3-70a99c21f502', 'concept'::public.curated_course_node_type, 'Numerical approximation from grids or sampled data', null, 3),
  ('0f4ce4f4-4cfe-43a2-a154-05cf03919954', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'c86c562e-5d48-4b58-8ada-4d7c90d6a024', 'subtopic'::public.curated_course_node_type, 'General regions and changing order', 'Type I and Type II descriptions expose different slicing choices. Reversing order can turn an impossible integral into a simple one.', 1),
  ('cbd2ea74-9a37-4fdd-86a8-e6fa0f1161aa', 'af13c9a6-3073-4e40-8a59-424a699b978b', '0f4ce4f4-4cfe-43a2-a154-05cf03919954', 'concept'::public.curated_course_node_type, 'Vertically and horizontally simple regions', null, 0),
  ('e5d8ea75-2a88-4660-9e1c-fa2b8b993a86', 'af13c9a6-3073-4e40-8a59-424a699b978b', '0f4ce4f4-4cfe-43a2-a154-05cf03919954', 'concept'::public.curated_course_node_type, 'Sketching bounds before integrating', null, 1),
  ('47e5b9f0-5599-404e-bb68-253f090a3922', 'af13c9a6-3073-4e40-8a59-424a699b978b', '0f4ce4f4-4cfe-43a2-a154-05cf03919954', 'concept'::public.curated_course_node_type, 'Changing the order of integration', null, 2),
  ('549bd2ef-793e-492d-8b05-a3ff5ced43d6', 'af13c9a6-3073-4e40-8a59-424a699b978b', '0f4ce4f4-4cfe-43a2-a154-05cf03919954', 'concept'::public.curated_course_node_type, 'Splitting non-simple regions into valid pieces', null, 3),
  ('6585d0b5-a5ca-4174-b6ce-a9ea4a2d8876', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'c86c562e-5d48-4b58-8ada-4d7c90d6a024', 'subtopic'::public.curated_course_node_type, 'Polar coordinates and planar applications', 'Polar coordinates match circular and radial symmetry, with the factor r accounting for how area scales away from the origin.', 2),
  ('bb8ee703-62a3-42b8-88a5-cec4aaf97756', 'af13c9a6-3073-4e40-8a59-424a699b978b', '6585d0b5-a5ca-4174-b6ce-a9ea4a2d8876', 'concept'::public.curated_course_node_type, 'Cartesian-polar conversion and polar regions', null, 0),
  ('9a022d32-b7e7-4ea1-b4ec-f017316a31ce', 'af13c9a6-3073-4e40-8a59-424a699b978b', '6585d0b5-a5ca-4174-b6ce-a9ea4a2d8876', 'concept'::public.curated_course_node_type, 'Area element dA = r dr dtheta', null, 1),
  ('301bc99b-b4c8-4bd0-adc5-061200acb846', 'af13c9a6-3073-4e40-8a59-424a699b978b', '6585d0b5-a5ca-4174-b6ce-a9ea4a2d8876', 'concept'::public.curated_course_node_type, 'Mass, moments, center of mass, and probability density', null, 2),
  ('fd6fee65-2cd1-4f9b-ba49-e3c1ff89c1d3', 'af13c9a6-3073-4e40-8a59-424a699b978b', '6585d0b5-a5ca-4174-b6ce-a9ea4a2d8876', 'concept'::public.curated_course_node_type, 'Radially symmetric models and normalization checks', null, 3),
  ('e07f34ad-c09b-4f70-b609-2721ede03a5d', 'af13c9a6-3073-4e40-8a59-424a699b978b', null, 'topic'::public.curated_course_node_type, 'Triple Integrals, Coordinate Systems, and Change of Variables', 'Triple integrals extend accumulation to volumes, while a general change of variables adapts the coordinate grid to the geometry. The Jacobian determinant measures the local scaling of area or volume under that transformation.', 7),
  ('e8cd7db6-c1a1-4fbe-b051-724b65457173', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'e07f34ad-c09b-4f70-b609-2721ede03a5d', 'subtopic'::public.curated_course_node_type, 'Triple integrals in rectangular coordinates', 'A three-dimensional region can be sliced and projected in several ways. A clear sketch and consistent bounds are essential.', 0),
  ('bed5b696-9461-4f59-9ac7-7a129e02fc83', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'e8cd7db6-c1a1-4fbe-b051-724b65457173', 'concept'::public.curated_course_node_type, 'Iterated triple integrals and order of integration', null, 0),
  ('3aec4cd5-8487-40db-8e4d-9560abe00b3f', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'e8cd7db6-c1a1-4fbe-b051-724b65457173', 'concept'::public.curated_course_node_type, 'Describing solids by projections and bounding surfaces', null, 1),
  ('36ebebb5-f284-4290-be40-b2c60e531415', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'e8cd7db6-c1a1-4fbe-b051-724b65457173', 'concept'::public.curated_course_node_type, 'Volume, mass, average value, and center of mass', null, 2),
  ('baf98cf9-4d81-457d-bfa3-ce7471043dbe', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'e8cd7db6-c1a1-4fbe-b051-724b65457173', 'concept'::public.curated_course_node_type, 'Probability densities and normalization in three dimensions', null, 3),
  ('3c4a32d7-ca32-4a84-9f4b-c090b61b61ca', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'e07f34ad-c09b-4f70-b609-2721ede03a5d', 'subtopic'::public.curated_course_node_type, 'Cylindrical and spherical coordinates', 'Coordinate systems based on rotational symmetry can simplify both the region and the integrand when their volume elements are derived and used correctly.', 1),
  ('afb9c121-5853-4193-9629-9bbcb318e1c1', 'af13c9a6-3073-4e40-8a59-424a699b978b', '3c4a32d7-ca32-4a84-9f4b-c090b61b61ca', 'concept'::public.curated_course_node_type, 'Coordinate conversion and geometric ranges', null, 0),
  ('a67a5f7d-f515-45e3-9b03-20c65d4357f3', 'af13c9a6-3073-4e40-8a59-424a699b978b', '3c4a32d7-ca32-4a84-9f4b-c090b61b61ca', 'concept'::public.curated_course_node_type, 'Cylindrical volume element r dz dr dtheta', null, 1),
  ('909b6671-e113-434d-ac98-1e491d168318', 'af13c9a6-3073-4e40-8a59-424a699b978b', '3c4a32d7-ca32-4a84-9f4b-c090b61b61ca', 'concept'::public.curated_course_node_type, 'Spherical volume element rho^2 sin(phi) d rho d phi dtheta', null, 2),
  ('73b21899-fa28-4606-9ed1-f06c3bc21c30', 'af13c9a6-3073-4e40-8a59-424a699b978b', '3c4a32d7-ca32-4a84-9f4b-c090b61b61ca', 'concept'::public.curated_course_node_type, 'Applications to pipes, tanks, spheres, fields, and radial densities', null, 3),
  ('68d5ff07-830c-4179-a1fe-aa8d37f5104a', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'e07f34ad-c09b-4f70-b609-2721ede03a5d', 'subtopic'::public.curated_course_node_type, 'General transformations and Jacobians', 'A change of variables replaces a difficult region with a simpler one while the absolute Jacobian determinant preserves the correct local measure.', 2),
  ('4a225ebf-4b41-4839-b19c-836a3dc939c9', 'af13c9a6-3073-4e40-8a59-424a699b978b', '68d5ff07-830c-4179-a1fe-aa8d37f5104a', 'concept'::public.curated_course_node_type, 'Mapping regions between coordinate planes', null, 0),
  ('d8562dfb-057d-4517-8020-6fccaa2a24ea', 'af13c9a6-3073-4e40-8a59-424a699b978b', '68d5ff07-830c-4179-a1fe-aa8d37f5104a', 'concept'::public.curated_course_node_type, 'Computing and interpreting a 2D or 3D Jacobian determinant', null, 1),
  ('82a74037-6083-4eff-8a74-a9f380719fae', 'af13c9a6-3073-4e40-8a59-424a699b978b', '68d5ff07-830c-4179-a1fe-aa8d37f5104a', 'concept'::public.curated_course_node_type, 'One-to-one conditions, orientation, and absolute value', null, 2),
  ('95066e30-a9c9-4fc2-b5fe-1f4fe69fd3b5', 'af13c9a6-3073-4e40-8a59-424a699b978b', '68d5ff07-830c-4179-a1fe-aa8d37f5104a', 'concept'::public.curated_course_node_type, 'Nonlinear transformations, scaling, and verification by alternate methods', null, 3),
  ('15bea76e-47bd-43ff-91c8-352c8bf66804', 'af13c9a6-3073-4e40-8a59-424a699b978b', null, 'topic'::public.curated_course_node_type, 'Vector Fields, Line Integrals, and Conservative Fields', 'Vector fields assign a vector to each point, representing velocity, force, electrical influence, gradients, or transport. Line integrals measure accumulated work, circulation, or scalar density along a curve.', 8),
  ('7ad9549a-26f3-43d8-9d6c-a947bbcf547e', 'af13c9a6-3073-4e40-8a59-424a699b978b', '15bea76e-47bd-43ff-91c8-352c8bf66804', 'subtopic'::public.curated_course_node_type, 'Visualizing and interpreting vector fields', 'A field plot, streamlines, and local vectors reveal direction and magnitude before any integral is computed.', 0),
  ('de3d354f-dcd5-4fce-9c6a-847b96cc0828', 'af13c9a6-3073-4e40-8a59-424a699b978b', '7ad9549a-26f3-43d8-9d6c-a947bbcf547e', 'concept'::public.curated_course_node_type, 'Vector fields in the plane and space', null, 0),
  ('ace9f345-6db8-4596-aeef-5937460df2f7', 'af13c9a6-3073-4e40-8a59-424a699b978b', '7ad9549a-26f3-43d8-9d6c-a947bbcf547e', 'concept'::public.curated_course_node_type, 'Flow lines, sources, sinks, rotation, and qualitative behavior', null, 1),
  ('9862ef25-77b9-4788-8303-5f8d8aaf8c8a', 'af13c9a6-3073-4e40-8a59-424a699b978b', '7ad9549a-26f3-43d8-9d6c-a947bbcf547e', 'concept'::public.curated_course_node_type, 'Gradient fields and physical examples', null, 2),
  ('951d3e7e-3243-427f-a689-86d0f087f7da', 'af13c9a6-3073-4e40-8a59-424a699b978b', '7ad9549a-26f3-43d8-9d6c-a947bbcf547e', 'concept'::public.curated_course_node_type, 'Domain restrictions and singularities', null, 3),
  ('88db7f39-bcf8-40a8-a85a-1c9223f4a7cf', 'af13c9a6-3073-4e40-8a59-424a699b978b', '15bea76e-47bd-43ff-91c8-352c8bf66804', 'subtopic'::public.curated_course_node_type, 'Scalar and vector line integrals', 'The line element determines whether the integral accumulates scalar density along length or the tangential component of a vector field along motion.', 1),
  ('2193ea6e-10b5-46e7-978d-a3e201d0fcb8', 'af13c9a6-3073-4e40-8a59-424a699b978b', '88db7f39-bcf8-40a8-a85a-1c9223f4a7cf', 'concept'::public.curated_course_node_type, 'Scalar line integrals with respect to arc length', null, 0),
  ('cd298ddb-b4c0-410d-8fda-9b6fe65a09a6', 'af13c9a6-3073-4e40-8a59-424a699b978b', '88db7f39-bcf8-40a8-a85a-1c9223f4a7cf', 'concept'::public.curated_course_node_type, 'Work and circulation integrals F dot dr', null, 1),
  ('264b5f05-4fdd-466f-85f5-7b8b2268776b', 'af13c9a6-3073-4e40-8a59-424a699b978b', '88db7f39-bcf8-40a8-a85a-1c9223f4a7cf', 'concept'::public.curated_course_node_type, 'Parameterization, orientation, and reparameterization invariance', null, 2),
  ('585b1767-dce5-402e-a6f5-33aa18794626', 'af13c9a6-3073-4e40-8a59-424a699b978b', '88db7f39-bcf8-40a8-a85a-1c9223f4a7cf', 'concept'::public.curated_course_node_type, 'Piecewise smooth curves and dimensional analysis', null, 3),
  ('d89faecd-72df-4c94-82d4-3be36b4223b2', 'af13c9a6-3073-4e40-8a59-424a699b978b', '15bea76e-47bd-43ff-91c8-352c8bf66804', 'subtopic'::public.curated_course_node_type, 'Conservative fields and potential functions', 'When a field is a gradient, work depends only on endpoints. This converts a path integral into a potential difference and exposes energy structure.', 2),
  ('191737a9-aefc-4dd1-9f19-e02c223e3877', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'd89faecd-72df-4c94-82d4-3be36b4223b2', 'concept'::public.curated_course_node_type, 'Potential functions and exact differentials', null, 0),
  ('4f7977ee-86de-4410-af31-683c6925d88f', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'd89faecd-72df-4c94-82d4-3be36b4223b2', 'concept'::public.curated_course_node_type, 'Fundamental Theorem for Line Integrals', null, 1),
  ('4c72c6b9-db33-49a9-9fb9-7ebb9bcf0892', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'd89faecd-72df-4c94-82d4-3be36b4223b2', 'concept'::public.curated_course_node_type, 'Path independence and closed-loop tests', null, 2),
  ('eb1cf83b-bbe7-4854-91ba-99040bae1a22', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'd89faecd-72df-4c94-82d4-3be36b4223b2', 'concept'::public.curated_course_node_type, 'Curl-free criteria, simply connected domains, and important caveats', null, 3),
  ('724702c3-2619-4932-8a42-c8daca72ce77', 'af13c9a6-3073-4e40-8a59-424a699b978b', null, 'topic'::public.curated_course_node_type, 'Green''s Theorem in the Plane', 'Green''s theorem equates circulation or flux around a closed planar boundary with a double integral over the enclosed region. It is the first major example of a boundary-interior principle that unifies vector calculus.', 9),
  ('8c5ac098-b8ad-43d0-9583-8f13385b58e8', 'af13c9a6-3073-4e40-8a59-424a699b978b', '724702c3-2619-4932-8a42-c8daca72ce77', 'subtopic'::public.curated_course_node_type, 'Circulation form', 'The circulation form converts a positively oriented boundary integral into the accumulated scalar curl over the region.', 0),
  ('d6f6921b-0bf8-46a5-b41b-84dd8442ffcf', 'af13c9a6-3073-4e40-8a59-424a699b978b', '8c5ac098-b8ad-43d0-9583-8f13385b58e8', 'concept'::public.curated_course_node_type, 'Statement, hypotheses, and positive orientation', null, 0),
  ('a607a16b-ea84-433b-b387-676256cc9a19', 'af13c9a6-3073-4e40-8a59-424a699b978b', '8c5ac098-b8ad-43d0-9583-8f13385b58e8', 'concept'::public.curated_course_node_type, 'Piecewise smooth simple closed curves', null, 1),
  ('4035fbcd-7e31-4d86-b2b7-55f114ea3a2d', 'af13c9a6-3073-4e40-8a59-424a699b978b', '8c5ac098-b8ad-43d0-9583-8f13385b58e8', 'concept'::public.curated_course_node_type, 'Computing circulation from a double integral', null, 2),
  ('4b008da5-2b92-4436-94e2-83c444dbb8e7', 'af13c9a6-3073-4e40-8a59-424a699b978b', '8c5ac098-b8ad-43d0-9583-8f13385b58e8', 'concept'::public.curated_course_node_type, 'Computing a difficult double integral from a boundary integral', null, 3),
  ('2444a1d9-b3dc-4610-9d65-efa6e354eb6f', 'af13c9a6-3073-4e40-8a59-424a699b978b', '724702c3-2619-4932-8a42-c8daca72ce77', 'subtopic'::public.curated_course_node_type, 'Flux form and planar divergence', 'The flux form relates outward flow across a boundary to net source strength within the region.', 1),
  ('82d90f86-872c-4069-bc2b-2c7ddeaa473c', 'af13c9a6-3073-4e40-8a59-424a699b978b', '2444a1d9-b3dc-4610-9d65-efa6e354eb6f', 'concept'::public.curated_course_node_type, 'Planar divergence and outward normal orientation', null, 0),
  ('408829c3-7fab-43cd-9390-5358a4da1f1f', 'af13c9a6-3073-4e40-8a59-424a699b978b', '2444a1d9-b3dc-4610-9d65-efa6e354eb6f', 'concept'::public.curated_course_node_type, 'Flux form of Green''s theorem', null, 1),
  ('4b6784b8-8d70-4ec9-9016-4af27459b79c', 'af13c9a6-3073-4e40-8a59-424a699b978b', '2444a1d9-b3dc-4610-9d65-efa6e354eb6f', 'concept'::public.curated_course_node_type, 'Sources, sinks, and conservation interpretation', null, 2),
  ('12a26d23-9390-4060-b726-90bd7fea5993', 'af13c9a6-3073-4e40-8a59-424a699b978b', '2444a1d9-b3dc-4610-9d65-efa6e354eb6f', 'concept'::public.curated_course_node_type, 'Connections between circulation and flux forms', null, 3),
  ('91c16d98-e13c-40a1-b4eb-227b37cb39ee', 'af13c9a6-3073-4e40-8a59-424a699b978b', '724702c3-2619-4932-8a42-c8daca72ce77', 'subtopic'::public.curated_course_node_type, 'Area and multiply connected regions', 'Green''s theorem can compute area and remains valid on regions with holes when every boundary component receives the correct induced orientation.', 2),
  ('3f71cfdb-1213-44f8-95bf-1e0ea78ed3f2', 'af13c9a6-3073-4e40-8a59-424a699b978b', '91c16d98-e13c-40a1-b4eb-227b37cb39ee', 'concept'::public.curated_course_node_type, 'Area formulas derived from Green''s theorem', null, 0),
  ('445c6e7c-8df9-494f-9bac-41992452100c', 'af13c9a6-3073-4e40-8a59-424a699b978b', '91c16d98-e13c-40a1-b4eb-227b37cb39ee', 'concept'::public.curated_course_node_type, 'Inner and outer boundary orientation', null, 1),
  ('203c1f1a-a738-48bd-9cf4-c93bac5e63fa', 'af13c9a6-3073-4e40-8a59-424a699b978b', '91c16d98-e13c-40a1-b4eb-227b37cb39ee', 'concept'::public.curated_course_node_type, 'Removing singularities and decomposing regions', null, 2),
  ('1ade1696-da83-42d0-a5ab-ff07c5d7dabc', 'af13c9a6-3073-4e40-8a59-424a699b978b', '91c16d98-e13c-40a1-b4eb-227b37cb39ee', 'concept'::public.curated_course_node_type, 'Hypothesis checks and counterexamples', null, 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('e62e9945-24e0-48c4-a6b3-4ef06ba1dd02', 'af13c9a6-3073-4e40-8a59-424a699b978b', null, 'topic'::public.curated_course_node_type, 'Parametric Surfaces and Surface Integrals', 'Parametric surfaces generalize parametrized curves to two parameters. Their tangent vectors determine local area and orientation, enabling surface area, distributed mass, and flux calculations on curved geometry.', 10),
  ('4f8f299a-b2b3-434f-a1cb-f2efb5850d0a', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'e62e9945-24e0-48c4-a6b3-4ef06ba1dd02', 'subtopic'::public.curated_course_node_type, 'Parametrizing surfaces', 'A good parameterization covers the intended surface once, makes the boundary visible, and matches the geometry of the problem.', 0),
  ('d1906c3c-34a8-4db5-95b2-befd8924b68d', 'af13c9a6-3073-4e40-8a59-424a699b978b', '4f8f299a-b2b3-434f-a1cb-f2efb5850d0a', 'concept'::public.curated_course_node_type, 'Graphs, planes, cylinders, spheres, and surfaces of revolution', null, 0),
  ('8579d01d-0e20-4ba7-ac42-55566bd6520a', 'af13c9a6-3073-4e40-8a59-424a699b978b', '4f8f299a-b2b3-434f-a1cb-f2efb5850d0a', 'concept'::public.curated_course_node_type, 'Parameter domains and regularity', null, 1),
  ('e9fc9354-ee52-4538-b4be-8d63249a902e', 'af13c9a6-3073-4e40-8a59-424a699b978b', '4f8f299a-b2b3-434f-a1cb-f2efb5850d0a', 'concept'::public.curated_course_node_type, 'Tangent vectors and tangent planes', null, 2),
  ('ade8a314-f63a-4894-93b5-0749da0854f8', 'af13c9a6-3073-4e40-8a59-424a699b978b', '4f8f299a-b2b3-434f-a1cb-f2efb5850d0a', 'concept'::public.curated_course_node_type, 'Orientation and consistent normal vectors', null, 3),
  ('f59fc103-47c5-4ccb-a218-07676348c6ed', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'e62e9945-24e0-48c4-a6b3-4ef06ba1dd02', 'subtopic'::public.curated_course_node_type, 'Surface area and scalar surface integrals', 'The magnitude of the cross product of tangent vectors converts parameter-space area into true surface area.', 1),
  ('b1876dc6-82fe-4401-a1ca-378036da9e9c', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'f59fc103-47c5-4ccb-a218-07676348c6ed', 'concept'::public.curated_course_node_type, 'Surface element dS from a parameterization', null, 0),
  ('8e5d0011-793f-4546-bdd8-ecf1c9846d5c', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'f59fc103-47c5-4ccb-a218-07676348c6ed', 'concept'::public.curated_course_node_type, 'Surface area of graphs and parametrized surfaces', null, 1),
  ('42a25120-54ce-4f65-91b4-993d961ef5eb', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'f59fc103-47c5-4ccb-a218-07676348c6ed', 'concept'::public.curated_course_node_type, 'Mass or charge distributed on a surface', null, 2),
  ('b0b02513-0868-43e8-b983-46bb1ae5b628', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'f59fc103-47c5-4ccb-a218-07676348c6ed', 'concept'::public.curated_course_node_type, 'Avoiding double coverage and checking symmetry', null, 3),
  ('0c38ce92-9e9e-47ac-a191-a6653adb6fc8', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'e62e9945-24e0-48c4-a6b3-4ef06ba1dd02', 'subtopic'::public.curated_course_node_type, 'Flux integrals', 'A flux integral measures the component of a vector field passing through an oriented surface and is fundamental to transport and conservation laws.', 2),
  ('1da85e2e-67c8-4bf1-9523-f0ec2d3b0a3b', 'af13c9a6-3073-4e40-8a59-424a699b978b', '0c38ce92-9e9e-47ac-a191-a6653adb6fc8', 'concept'::public.curated_course_node_type, 'Oriented vector area element', null, 0),
  ('f7ad9d99-cdce-4382-a396-6126cc4ca010', 'af13c9a6-3073-4e40-8a59-424a699b978b', '0c38ce92-9e9e-47ac-a191-a6653adb6fc8', 'concept'::public.curated_course_node_type, 'Flux through graphs and parametrized surfaces', null, 1),
  ('2bac3f0b-eea2-450a-92bc-ca052d75e464', 'af13c9a6-3073-4e40-8a59-424a699b978b', '0c38ce92-9e9e-47ac-a191-a6653adb6fc8', 'concept'::public.curated_course_node_type, 'Open versus closed surfaces', null, 2),
  ('88541c9f-7f3a-434a-acff-47a8008ff99d', 'af13c9a6-3073-4e40-8a59-424a699b978b', '0c38ce92-9e9e-47ac-a191-a6653adb6fc8', 'concept'::public.curated_course_node_type, 'Applications to fluid flow, heat, electromagnetism, and membranes', null, 3),
  ('6c96b3ce-e5cc-42e6-836e-1d2e4364d731', 'af13c9a6-3073-4e40-8a59-424a699b978b', null, 'topic'::public.curated_course_node_type, 'Divergence, Curl, Stokes'' Theorem, and the Divergence Theorem', 'The capstone of multivariable calculus connects local differential measurements to global boundary integrals. Curl measures local rotation, divergence measures net outflow, and the major integral theorems turn these local quantities into circulation and flux laws.', 11),
  ('1a2dcd45-0857-4f44-94d6-e934e3be12b7', 'af13c9a6-3073-4e40-8a59-424a699b978b', '6c96b3ce-e5cc-42e6-836e-1d2e4364d731', 'subtopic'::public.curated_course_node_type, 'Divergence and curl', 'These operators summarize complementary field behavior and support qualitative reasoning before computation.', 0),
  ('46489e06-ef04-4f69-8688-9fc20a3ba07a', 'af13c9a6-3073-4e40-8a59-424a699b978b', '1a2dcd45-0857-4f44-94d6-e934e3be12b7', 'concept'::public.curated_course_node_type, 'Computing and interpreting divergence', null, 0),
  ('b217b55f-d1e5-470b-ab24-6f8398e52488', 'af13c9a6-3073-4e40-8a59-424a699b978b', '1a2dcd45-0857-4f44-94d6-e934e3be12b7', 'concept'::public.curated_course_node_type, 'Computing and interpreting curl', null, 1),
  ('32db225c-b353-4fe8-bf17-7365f1973e04', 'af13c9a6-3073-4e40-8a59-424a699b978b', '1a2dcd45-0857-4f44-94d6-e934e3be12b7', 'concept'::public.curated_course_node_type, 'Identities such as div(curl F)=0 and curl(grad f)=0', null, 2),
  ('faac8cf3-1235-4e0d-a21f-685fa148e989', 'af13c9a6-3073-4e40-8a59-424a699b978b', '1a2dcd45-0857-4f44-94d6-e934e3be12b7', 'concept'::public.curated_course_node_type, 'Smoothness, domains, singularities, and physical units', null, 3),
  ('5d9afa0e-6182-4b0a-aacd-d6030a2a5313', 'af13c9a6-3073-4e40-8a59-424a699b978b', '6c96b3ce-e5cc-42e6-836e-1d2e4364d731', 'subtopic'::public.curated_course_node_type, 'Stokes'' theorem', 'Stokes'' theorem relates circulation around a boundary curve to the flux of curl through any compatible spanning surface.', 1),
  ('f5c1a36b-fa63-4243-8e1f-3363093b7188', 'af13c9a6-3073-4e40-8a59-424a699b978b', '5d9afa0e-6182-4b0a-aacd-d6030a2a5313', 'concept'::public.curated_course_node_type, 'Statement, hypotheses, boundary orientation, and right-hand rule', null, 0),
  ('d1a8ce79-14fe-4b56-9a8a-0ac969d79bf6', 'af13c9a6-3073-4e40-8a59-424a699b978b', '5d9afa0e-6182-4b0a-aacd-d6030a2a5313', 'concept'::public.curated_course_node_type, 'Choosing a convenient spanning surface', null, 1),
  ('bfe14ed0-0d13-456f-8daf-5c71e3d7827d', 'af13c9a6-3073-4e40-8a59-424a699b978b', '5d9afa0e-6182-4b0a-aacd-d6030a2a5313', 'concept'::public.curated_course_node_type, 'Reducing line integrals to surface integrals and conversely', null, 2),
  ('d4c51196-32d0-47c6-a27d-9bb9fa03659f', 'af13c9a6-3073-4e40-8a59-424a699b978b', '5d9afa0e-6182-4b0a-aacd-d6030a2a5313', 'concept'::public.curated_course_node_type, 'Green''s theorem as a planar special case', null, 3),
  ('cc5d3649-5d10-42f3-86ab-1053351271fc', 'af13c9a6-3073-4e40-8a59-424a699b978b', '6c96b3ce-e5cc-42e6-836e-1d2e4364d731', 'subtopic'::public.curated_course_node_type, 'Divergence theorem and synthesis', 'The divergence theorem relates outward flux through a closed surface to total divergence inside, providing a mathematical form of conservation.', 2),
  ('4416fd40-09fa-44b8-a2d5-ad1a212816e6', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'cc5d3649-5d10-42f3-86ab-1053351271fc', 'concept'::public.curated_course_node_type, 'Statement, hypotheses, outward orientation, and piecewise smooth boundaries', null, 0),
  ('678e20b9-11d3-4de2-bb84-7799cf61253d', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'cc5d3649-5d10-42f3-86ab-1053351271fc', 'concept'::public.curated_course_node_type, 'Choosing between direct flux and volume integration', null, 1),
  ('f5fddd6d-a786-4a19-b453-58b38cf9a59b', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'cc5d3649-5d10-42f3-86ab-1053351271fc', 'concept'::public.curated_course_node_type, 'Gauss-law, transport, continuity, and conservation applications', null, 2),
  ('c2458ad2-9a56-4f90-8830-92457108d79d', 'af13c9a6-3073-4e40-8a59-424a699b978b', 'cc5d3649-5d10-42f3-86ab-1053351271fc', 'concept'::public.curated_course_node_type, 'Unifying the Fundamental Theorem of Calculus, Green, Stokes, and divergence theorems', null, 3);
insert into public.curated_course_resources (course_id, kind, title, link_or_site, description, sort_order)
values
  ('af13c9a6-3073-4e40-8a59-424a699b978b', 'textbook'::public.curated_course_resource_kind, 'OpenStax Calculus Volume 3', 'https://openstax.org/details/books/calculus-volume-3', 'Best default open text for vectors, multivariable differentiation, multiple integrals, and vector calculus.', 0),
  ('af13c9a6-3073-4e40-8a59-424a699b978b', 'textbook'::public.curated_course_resource_kind, 'Calculus: Early Transcendentals', 'Cengage', 'James Stewart. Broad conventional coverage and a large exercise bank suitable for engineering and science fluency.', 1),
  ('af13c9a6-3073-4e40-8a59-424a699b978b', 'textbook'::public.curated_course_resource_kind, 'Thomas'' Calculus', 'Pearson', 'Clear multivariable reference with strong geometric examples and graded problem sets.', 2),
  ('af13c9a6-3073-4e40-8a59-424a699b978b', 'textbook'::public.curated_course_resource_kind, 'Vector Calculus', 'W. H. Freeman', 'Marsden and Tromba. Conceptually rich and more geometric treatment of derivatives, integrals, fields, and the integral theorems.', 3),
  ('af13c9a6-3073-4e40-8a59-424a699b978b', 'textbook'::public.curated_course_resource_kind, 'Vector Calculus, Linear Algebra, and Differential Forms', 'Matrix Editions', 'Hubbard and Hubbard. Advanced enrichment connecting derivative matrices, linear algebra, modern applications, and higher-dimensional reasoning.', 4),
  ('af13c9a6-3073-4e40-8a59-424a699b978b', 'textbook'::public.curated_course_resource_kind, 'Div, Grad, Curl, and All That', 'W. W. Norton', 'Schey. Compact intuition builder for vector operators, flux, circulation, and physical interpretations.', 5),
  ('af13c9a6-3073-4e40-8a59-424a699b978b', 'textbook'::public.curated_course_resource_kind, 'Mathematics for Economists', 'W. W. Norton', 'Simon and Blume. Economics supplement for multivariable optimization, comparative statics, and constrained models.', 6),
  ('af13c9a6-3073-4e40-8a59-424a699b978b', 'website'::public.curated_course_resource_kind, 'MIT OpenCourseWare 18.02SC Multivariable Calculus', 'https://ocw.mit.edu/courses/18-02sc-multivariable-calculus-fall-2010/', 'Self-contained lectures, notes, problems, solutions, and exams spanning vectors, partial derivatives, multiple integrals, and vector calculus.', 7),
  ('af13c9a6-3073-4e40-8a59-424a699b978b', 'website'::public.curated_course_resource_kind, 'MIT Multivariable Calculus Recitation Notes (Fall 2024)', 'https://ocw.mit.edu/courses/res-18-016-multivariable-calculus-recitation-notes-fall-2024/', 'Problem-solving notes and exercises with solutions, including a brief linear-algebra foundation and the traditional 18.02 sequence.', 8),
  ('af13c9a6-3073-4e40-8a59-424a699b978b', 'website'::public.curated_course_resource_kind, 'Paul''s Online Math Notes - Calculus III', 'https://tutorial.math.lamar.edu/Classes/CalcIII/CalcIII.aspx', 'Concise explanations and many worked examples for curves, partial derivatives, multiple integrals, and vector calculus.', 9),
  ('af13c9a6-3073-4e40-8a59-424a699b978b', 'website'::public.curated_course_resource_kind, 'Khan Academy Multivariable Calculus', 'https://www.khanacademy.org/math/multivariable-calculus', 'Guided videos and practice for core vector, derivative, integral, and theorem skills.', 10),
  ('af13c9a6-3073-4e40-8a59-424a699b978b', 'website'::public.curated_course_resource_kind, 'Active Calculus Multivariable', 'https://activecalculus.org/multi/', 'Inquiry-oriented open materials emphasizing concepts, visualization, and active problem solving.', 11),
  ('af13c9a6-3073-4e40-8a59-424a699b978b', 'website'::public.curated_course_resource_kind, 'GeoGebra 3D Calculator', 'https://www.geogebra.org/3d', 'Interactive visualization of surfaces, intersections, tangent planes, fields, and parameterized geometry.', 12),
